import React from 'react';

const degreeIcons = ['🎓', '📚', '✏️'];
const accentColors = [
  'linear-gradient(to bottom, #e8799a, #b882d4)',
  'linear-gradient(to bottom, #b882d4, #e8b96a)',
  'linear-gradient(to bottom, #e8b96a, #e8799a)',
];

const About = ({ data }) => {
  const education  = data?.education  || [];
  const languages  = data?.languages  || [];
  const softSkills = data?.softSkills || [];

  return (
    <section style={{ padding:'100px 0', position:'relative' }}>
      <div style={{ maxWidth:1100, margin:'0 auto', padding:'0 2rem' }}>

        {/* Header */}
        <div style={{ textAlign:'center', marginBottom:70 }}>
          <span style={{ fontFamily:"'DM Mono', monospace", fontSize:'0.78rem', letterSpacing:'0.3em', textTransform:'uppercase', color:'#e8799a', display:'block', marginBottom:'0.75rem' }}>
            ✦ 01. background
          </span>
          <h2 style={{ fontFamily:"'Cormorant Garamond', serif", fontSize:'clamp(2rem,5vw,3rem)', fontWeight:700, color:'#fdf0f4' }}>
            Education &amp; <span style={{ color:'#e8799a', fontStyle:'italic' }}>Background</span>
          </h2>
          <div style={{ width:60, height:3, background:'linear-gradient(90deg,#e8799a,#b882d4)', margin:'1.5rem auto 0', borderRadius:2 }} />
        </div>

        {/* Education Cards */}
        <div style={{ display:'flex', flexDirection:'column', gap:'1.25rem', marginBottom:'4rem' }}>
          {education.map((edu, i) => (
            <div key={i} style={{
              background:'rgba(34,18,40,0.72)', border:'1px solid rgba(232,121,154,0.14)',
              borderRadius:20, backdropFilter:'blur(14px)',
              padding:'1.75rem 2rem',
              display:'grid', gridTemplateColumns:'auto 1fr auto',
              gap:'1.5rem', alignItems:'center',
              transition:'all 0.3s ease', position:'relative', overflow:'hidden',
            }}
            onMouseEnter={e => { e.currentTarget.style.borderColor='rgba(232,121,154,0.4)'; e.currentTarget.style.boxShadow='0 0 30px rgba(232,121,154,0.12)'; e.currentTarget.style.transform='translateY(-3px)'; }}
            onMouseLeave={e => { e.currentTarget.style.borderColor='rgba(232,121,154,0.14)'; e.currentTarget.style.boxShadow='none'; e.currentTarget.style.transform='translateY(0)'; }}
            >
              <div style={{ position:'absolute', left:0, top:0, bottom:0, width:3, background:accentColors[i], borderRadius:'3px 0 0 3px' }} />
              <div style={{
                width:52, height:52, borderRadius:'50%',
                background:'rgba(232,121,154,0.1)',
                border:'1px solid rgba(232,121,154,0.25)',
                display:'flex', alignItems:'center', justifyContent:'center',
                fontSize:'1.5rem', flexShrink:0, marginLeft:'0.5rem',
              }}>{degreeIcons[i]}</div>
              <div>
                <h3 style={{ fontFamily:"'Cormorant Garamond', serif", fontSize:'1.15rem', fontWeight:700, color:'#fdf0f4', marginBottom:'0.25rem' }}>{edu.degree}</h3>
                <p style={{ fontSize:'0.88rem', color:'#e8799a', fontFamily:"'Nunito'", marginBottom:'0.1rem' }}>{edu.institution}</p>
              </div>
              <div style={{ textAlign:'right', flexShrink:0 }}>
                <div style={{ fontFamily:"'DM Mono'", fontSize:'1.05rem', fontWeight:600, color:'#e8b96a', marginBottom:'0.25rem' }}>{edu.score}</div>
                <div style={{ fontFamily:"'Nunito'", fontSize:'0.8rem', color:'rgba(253,240,244,0.45)' }}>{edu.year}</div>
              </div>
            </div>
          ))}
        </div>

        {/* Languages & Soft Skills */}
        <div style={{ display:'grid', gridTemplateColumns:'repeat(auto-fit,minmax(280px,1fr))', gap:'1.5rem' }}>

          {/* Languages */}
          <div style={{ background:'rgba(34,18,40,0.72)', border:'1px solid rgba(232,121,154,0.14)', borderRadius:20, backdropFilter:'blur(14px)', padding:'1.75rem' }}>
            <h3 style={{ fontFamily:"'Cormorant Garamond', serif", fontSize:'1.2rem', fontWeight:700, color:'#fdf0f4', marginBottom:'1.5rem', display:'flex', alignItems:'center', gap:'0.5rem' }}>
              🌐 Languages
            </h3>
            {languages.map((lang, i) => (
              <div key={i} style={{ marginBottom:'1.25rem' }}>
                <div style={{ display:'flex', justifyContent:'space-between', marginBottom:'0.4rem' }}>
                  <span style={{ fontFamily:"'Nunito'", fontSize:'0.9rem', color:'#fdf0f4' }}>{lang.name}</span>
                  <span style={{ fontFamily:"'DM Mono'", fontSize:'0.78rem', color:'#e8799a' }}>{lang.proficiency}</span>
                </div>
                <div style={{ height:5, background:'rgba(255,255,255,0.06)', borderRadius:3, overflow:'hidden' }}>
                  <div style={{ height:'100%', width:`${lang.level}%`, background:'linear-gradient(90deg,#e8799a,#b882d4)', borderRadius:3, transition:'width 1s ease' }} />
                </div>
              </div>
            ))}
          </div>

          {/* Soft Skills */}
          <div style={{ background:'rgba(34,18,40,0.72)', border:'1px solid rgba(232,121,154,0.14)', borderRadius:20, backdropFilter:'blur(14px)', padding:'1.75rem' }}>
            <h3 style={{ fontFamily:"'Cormorant Garamond', serif", fontSize:'1.2rem', fontWeight:700, color:'#fdf0f4', marginBottom:'1.5rem', display:'flex', alignItems:'center', gap:'0.5rem' }}>
              💡 Soft Skills
            </h3>
            <div style={{ display:'flex', flexWrap:'wrap', gap:'0.6rem' }}>
              {softSkills.map((skill, i) => (
                <span key={i} style={{
                  padding:'0.4rem 1rem',
                  background:'rgba(232,185,106,0.08)',
                  border:'1px solid rgba(232,185,106,0.22)',
                  borderRadius:'50px',
                  fontFamily:"'Nunito'", fontSize:'0.85rem', color:'#e8b96a',
                }}>{skill}</span>
              ))}
            </div>
          </div>
        </div>
      </div>
    </section>
  );
};

export default About;
